// Resized webp through the media service, aspect kept (size = long side); crop in CSS with lookRefPos.
export function lookRefUrl(label, size = 480) {
  const r = LOOK_REFS[label];
  if (!r) return null;
  const stem = r.file.replace(/\.[a-z]+$/i, '');
  return `${LOOK_REF_HOST}${r.file}/v1/fit/w_${size},h_${size},q_80,enc_webp,quality_auto/${stem}.webp`;
}
export const lookRefPos = (label) => LOOK_REFS[label]?.pos || '50% 35%';

